/**
 * App bootstrap: a phone-first shell with a bottom navigation bar.
 * Primary sections (Home, Markets, History) are polished views; the
 * advanced analysis tools live under "Tools". Views render lazily; all
 * analysis lives in src/core.
 */

import { inject } from '@vercel/analytics';
import { initDataSource, type ActiveDataSource } from './dataSource';
import { fetchSnapshot, findBtcSymbol } from './markets';
import { formatPrice, formatPct } from './format';
import { renderCryptoView } from './views/cryptoView';
import { renderStocksView } from './views/stocksView';
import { renderMarketsView } from './views/marketsView';
import { renderValueView } from './views/valueView';
import { renderBacktestView } from './views/backtestView';
import { renderGridView } from './views/gridView';
import { renderMarketScanView } from './views/marketScanView';
import { renderMonitoringView } from './views/monitoringView';
import { renderPortfolioView } from './views/portfolioView';
import { renderValidationView } from './views/validationView';
import type { ViewHandle } from './viewLifecycle';
import { showToast, showSuccess, showError, showInfo, showWarning } from './toastNotifications';
import {
  showLoadingOverlay,
  hideLoadingOverlay,
  createLoadingSpinner,
  showEmptyState,
} from './loadingStates';

// Export UI helpers globally for view code
declare global {
  interface Window {
    toast: {
      show: typeof showToast;
      success: typeof showSuccess;
      error: typeof showError;
      info: typeof showInfo;
      warning: typeof showWarning;
    };
    loading: {
      show: typeof showLoadingOverlay;
      hide: typeof hideLoadingOverlay;
      spinner: typeof createLoadingSpinner;
      empty: typeof showEmptyState;
    };
  }
}

type ViewRenderer = (container: HTMLElement, data: ActiveDataSource) => ViewHandle | void;

const PRIMARY_VIEWS: Record<string, ViewRenderer> = {
  crypto: renderCryptoView,
  stocks: renderStocksView,
  value: renderValueView,
  markets: renderMarketsView,
};

const TOOL_VIEWS: Record<string, ViewRenderer | null> = {
  scan: renderMarketScanView,
  backtest: renderBacktestView,
  validation: renderValidationView,
  portfolio: renderPortfolioView,
  grid: renderGridView,
  monitoring: renderMonitoringView,
  learn: null,
};

function showBanner(data: ActiveDataSource): void {
  const banner = document.getElementById('data-source-banner');
  if (!banner) return;
  banner.hidden = false;
  if (data.kind === 'revolut') {
    banner.classList.add('live');
    banner.textContent = `Connected to ${data.source.name} — live data, read-only.`;
  } else if (data.kind === 'public') {
    banner.classList.add('live');
    banner.textContent = `Live market data (${data.source.name.replace(' (read-only)', '')}) — read-only.`;
  } else {
    // The raw diagnostics (failed fetch URLs, full error text) are real and
    // worth keeping for anyone actually debugging a data-source outage, but
    // showing them inline made this banner ~180px tall on EVERY screen (the
    // first thing rendered, above literally all real content) — confirmed
    // via screenshot, not just reasoning about the markup. A consumer-facing
    // trading app should never open with a wall of stack-trace-like text.
    // Collapsed behind a native <details> disclosure: the short one-line
    // message is all that shows by default, the technical detail is one tap
    // away for whoever needs it (David debugging, or this session's own
    // verification screenshots), and <details> needs no JS to toggle.
    banner.textContent = '';
    const summary = document.createElement('span');
    summary.textContent = 'Live data unavailable — showing DEMO data, not real prices.';
    banner.appendChild(summary);
    if (data.diagnostics.length > 0) {
      const details = document.createElement('details');
      details.className = 'data-source-banner-details';
      const toggle = document.createElement('summary');
      toggle.textContent = 'Why?';
      details.appendChild(toggle);
      const reasons = document.createElement('div');
      reasons.className = 'data-source-banner-reasons';
      reasons.textContent = data.diagnostics.join(' · ');
      details.appendChild(reasons);
      banner.appendChild(details);
    }
  }
}

async function bootstrap(): Promise<void> {
  // Initialize Vercel Web Analytics
  inject();

  // Setup global UI helpers
  window.toast = {
    show: showToast,
    success: showSuccess,
    error: showError,
    info: showInfo,
    warning: showWarning,
  };
  window.loading = {
    show: showLoadingOverlay,
    hide: hideLoadingOverlay,
    spinner: createLoadingSpinner,
    empty: showEmptyState,
  };

  const data = await initDataSource();
  showBanner(data);

  const primaryMounted = new Set<string>();
  const toolsMounted = new Set<string>();
  const primaryHandles = new Map<string, ViewHandle>();
  let activeName: string | null = null;

  function activateView(name: string): void {
    document.querySelectorAll<HTMLElement>('.view').forEach((v) => {
      v.classList.toggle('active', v.id === `view-${name}`);
    });
    // The bottom nav is a real role="tablist"/role="tab" widget (index.html)
    // but this loop only ever toggled the VISUAL `.active` class — a screen
    // reader had no way to tell which tab was selected, since `aria-selected`
    // was never written after the very first (server-rendered) state. Also
    // restores the roving-tabindex convention (exactly one tab in the Tab
    // order at a time; the rest reachable via the arrow-key handler below) —
    // previously all four were separate Tab stops, which isn't the native
    // tablist pattern.
    // `value` (Home's "Portfolio value" drill-down) has no bottom-nav button
    // of its own — it's reached only via Home's hero card and its own "←
    // Home" back link — so without this alias every `.nav-btn` above failed
    // `b.dataset['nav'] === name` at once: all four lost `aria-selected` AND
    // dropped to `tabIndex: -1`, making the entire bottom nav unreachable by
    // Tab while this screen was open, with no tab shown as active either.
    const navName = name === 'value' ? 'crypto' : name;
    document.querySelectorAll<HTMLButtonElement>('.nav-btn').forEach((b) => {
      const active = b.dataset['nav'] === navName;
      b.classList.toggle('active', active);
      b.setAttribute('aria-selected', String(active));
      b.tabIndex = active ? 0 : -1;
    });
    if (activeName && activeName !== name) primaryHandles.get(activeName)?.pause();
    const renderer = PRIMARY_VIEWS[name];
    if (renderer) {
      const panel = document.getElementById(`view-${name}`);
      if (panel) {
        if (!primaryMounted.has(name)) {
          const handle = renderer(panel, data);
          if (handle) primaryHandles.set(name, handle);
          primaryMounted.add(name);
        } else {
          primaryHandles.get(name)?.resume();
        }
      }
    }
    activeName = name;
    if (name === 'tools') resetTools();
    window.scrollTo({ top: 0 });
  }

  // Remembers which tool card was last opened, purely so `resetTools` (the
  // "← Back to Tools" button) can return focus to it — see the comment
  // there for why this matters.
  let lastOpenedTab: string | null = null;

  // Plain DOM-state reset — shows the tool grid, hides the open tool. Used
  // both by the "← Back to Tools" button (see `backToToolsMenu` below, which
  // additionally manages focus for that specific action) and by
  // `activateView('tools')` itself (switching to the Tools nav tab by any
  // means — click, or the arrow-key tablist handler below — must show the
  // grid without redirecting focus away from the nav tab the user just
  // landed on).
  function resetTools(): void {
    const menu = document.getElementById('tools-menu');
    const detail = document.getElementById('tool-detail');
    if (menu) menu.hidden = false;
    if (detail) detail.hidden = true;
  }

  /** The "← Back to Tools" button's own handler: resets the tools DOM state
   * AND returns focus to the tool card that was open — unlike a plain
   * `activateView('tools')`, this action's own just-clicked control (inside
   * `#tool-detail`) is what becomes `hidden`, so without this a keyboard
   * user's focus silently drops to <body> with no visible indication of
   * where it went. */
  function backToToolsMenu(): void {
    resetTools();
    const menu = document.getElementById('tools-menu');
    const reopenTarget = lastOpenedTab
      ? document.querySelector<HTMLElement>(`[data-tab="${lastOpenedTab}"]`)
      : null;
    (reopenTarget ?? menu?.querySelector<HTMLElement>('[data-tab]'))?.focus();
  }

  function openTool(tab: string): void {
    const menu = document.getElementById('tools-menu');
    const detail = document.getElementById('tool-detail');
    if (menu) menu.hidden = true;
    if (detail) detail.hidden = false;
    document.querySelectorAll<HTMLElement>('.tab-panel').forEach((p) => {
      p.classList.toggle('active', p.id === `tab-${tab}`);
    });
    const renderer = TOOL_VIEWS[tab];
    if (renderer && !toolsMounted.has(tab)) {
      const panel = document.getElementById(`tab-${tab}`);
      if (panel) {
        renderer(panel, data);
        toolsMounted.add(tab);
      }
    }
    lastOpenedTab = tab;
    // Same focus-loss bug as `resetTools` above, the other direction: `menu`
    // (which contains the just-clicked tool-card button) becomes `hidden`,
    // so without this a keyboard user's focus silently vanishes to <body>
    // the moment a tool opens. The "← Back to Tools" button is always the
    // first real control in the newly-visible subtree, so it's a sensible,
    // predictable landing spot regardless of which tool just mounted.
    detail?.querySelector<HTMLElement>('[data-tool-back]')?.focus();
    window.scrollTo({ top: 0 });
  }

  // Delegated navigation: bottom-nav buttons and any [data-nav] link in views.
  document.addEventListener('click', (event) => {
    const target = event.target as HTMLElement;
    const nav = target.closest<HTMLElement>('[data-nav]');
    if (nav) {
      activateView(nav.dataset['nav']!);
      return;
    }
    const tool = target.closest<HTMLElement>('[data-tab]');
    if (tool) {
      openTool(tool.dataset['tab']!);
      return;
    }
    if (target.closest('[data-tool-back]')) backToToolsMenu();
  });

  // Every "obviously clickable" custom control across the app (Home's hero
  // balances, its Top-movers rows and Markets-strip cards, Stocks Overview's
  // hero, the topbar BTC chip) is a plain <div>/<section> with a click
  // handler and `role="button"` — real <button>s already get Enter/Space for
  // free from the browser, but a non-native element never does on its own.
  // Before this, every one of the above was reachable by mouse/touch only:
  // not in the Tab order, and even a screen-reader user who navigated onto
  // one by heading/landmark browsing had no key that did anything. One
  // delegated handler covers all of them (present and future) instead of
  // wiring a keydown listener per element.
  document.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const target = (event.target as HTMLElement).closest<HTMLElement>('[role="button"]');
    if (!target) return;
    event.preventDefault(); // Space must not also scroll the page
    target.click();
  });

  // Every role="tablist" in the app (bottom nav, Crypto/Stocks' Overview
  // sub-tabs, the Markets category tabs on both Crypto and Stocks Market
  // lists, Home's Gainers/Losers toggle) rendered `role="tab"` buttons with
  // correct `aria-selected`, but arrow-key movement between them — the
  // defining keyboard behaviour of the native ARIA tablist pattern, not an
  // optional extra — didn't exist anywhere: Left/Right/Home/End did nothing.
  // One delegated handler, keyed off the ARIA roles rather than any specific
  // class name, covers every tablist in the app at once. Clicking the newly
  // focused tab (not just focusing it) matches the "automatic activation"
  // tablist convention every one of these widgets already uses (its own
  // click handler is what actually switches the panel).
  document.addEventListener('keydown', (event) => {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    const tab = (event.target as HTMLElement).closest<HTMLElement>('[role="tab"]');
    if (!tab) return;
    const tablist = tab.closest<HTMLElement>('[role="tablist"]');
    if (!tablist) return;
    const tabs = Array.from(tablist.querySelectorAll<HTMLElement>(':scope > [role="tab"]'));
    const currentIndex = tabs.indexOf(tab);
    if (currentIndex === -1) return;
    let nextIndex = currentIndex;
    if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % tabs.length;
    else if (event.key === 'ArrowLeft') nextIndex = (currentIndex - 1 + tabs.length) % tabs.length;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = tabs.length - 1;
    event.preventDefault();
    const nextTab = tabs[nextIndex]!;
    nextTab.focus();
    nextTab.click();
  });

  // Set dark mode (always dark, no toggle)
  document.documentElement.setAttribute('data-theme', 'dark');

  activateView('crypto');
  void mountTopbarBtc(data);
}

/** Always-visible live Bitcoin chip in the top bar. */
async function mountTopbarBtc(data: ActiveDataSource): Promise<void> {
  const chip = document.getElementById('topbar-btc');
  if (!chip) return;
  const symbol = findBtcSymbol(data);
  if (!symbol) return;
  // The single most prominent live price in the whole header did nothing
  // when tapped. `data-nav="markets"` is all this needs — the delegated
  // [data-nav] click listener in bootstrap() picks up any element anywhere
  // in the document, not just bottom-nav buttons.
  chip.dataset['nav'] = 'markets';
  // A prior pass gave this chip a pointer cursor, hover tint, and a press
  // state — but a plain <div> is never in the Tab order and Enter/Space do
  // nothing on it regardless, so it was clickable by mouse/touch only.
  // role="button" + tabindex picks it up for free in both of bootstrap()'s
  // delegated keyboard handlers above (Enter/Space activation). Set only
  // once a real BTC symbol exists to point at — before that this chip never
  // becomes visible or clickable at all, so it must never be a keyboard
  // stop that does nothing.
  chip.setAttribute('role', 'button');
  chip.tabIndex = 0;
  async function tick(): Promise<void> {
    const snap = await fetchSnapshot(data, symbol!, 'Bitcoin');
    if (!snap || !chip) return;
    const up = snap.changePct >= 0;
    chip.hidden = false;
    chip.innerHTML = `<span class="tb-label">BTC</span><span class="tb-price">€${formatPrice(snap.price)}</span><span class="chg ${up ? 'up' : 'down'}">${formatPct(snap.changePct)}</span>`;
  }
  await tick();
  window.setInterval(() => void tick(), 20_000);
}

void bootstrap();
